import { evaluate, scorers } from './harness';
import cases from './cases/support.json'; // real questions, expert-approved answers

/**
 * Runs in CI on every change to a prompt, a model version, or the retrieval
 * pipeline. The gate is a regression check, not a target: we care that a
 * change did not make it worse, and by how much.
 */
const result = await evaluate({
  cases,
  run: async (question: string) => {
    const passages = await retrieve(question, { tenantId: 'eval', topK: 6 });
    return answer(question, passages);
  },
  scorers: [
    // Did it say the right thing?
    scorers.factualMatch({ against: (c) => c.expected }),

    // Is every claim traceable to a retrieved passage? An answer can be
    // correct and ungrounded, which is luck rather than a working system.
    scorers.groundedness({ passages: (r) => r.passages }),

    // Did it decline when retrieval found nothing relevant? The cases
    // deliberately include questions the documents cannot answer.
    scorers.abstainsWhenUnsupported(),
  ],
});

const baseline = await loadBaseline('support-answers');

// A 2% drop is noise; a 5% drop is a change someone needs to look at before
// it reaches customers.
if (result.factualMatch < baseline.factualMatch - 0.05) {
  throw new Error(
    `Accuracy regressed: ${pct(result.factualMatch)} vs ${pct(baseline.factualMatch)} baseline. ` +
      `Failing cases written to ${result.reportPath}`,
  );
}

if (result.groundedness < 0.95) {
  throw new Error(`Groundedness ${pct(result.groundedness)} — answers are drifting from the sources`);
}
